macro_rules! sum {
    ($($x:expr),*) => {
        {
            let mut total = 0;
            $(total += $x;)*
            total
        }
    };
}

fn main() {
    println!("{}", sum!(1, 2, 3, 4, 5));
    println!("{}", sum!(10));
}

macro_rules! using_x {
    ($e:expr) => {
        {
            let x = 42;
            $e
        }
    };
}

fn main() {
    let x = "hello";
    let result = using_x!(x.len());
    println!("{}", result);
}

macro_rules! info {
    ($($arg:tt)*) => {
        println!("[INFO] {}", ____!($($arg)*));
    };
}

fn main() {
    info!("Server started on port {}", 8080);
}

